#!/usr/bin/env bash\nset -euo pipefail\n\nSCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")/../src" && pwd)\nSCRIPT="$SCRIPT_DIR/check_title.sh"\n\n# Helper to create a temporary event JSON file\ncreate_event() {\n  local title="$1"\n  local tmpfile=$(mktemp)\n  cat > "$tmpfile" <<EOF\n{\n  "pull_request": {\n    "title": "$title"\n  }\n}\nEOF\n  echo "$tmpfile"\n}\n\n# Test 1: Title with correct prefix should succeed\nEVENT1=$(create_event "🚀 Add new feature")\nexport GITHUB_EVENT_PATH="$EVENT1"\nexport INPUT_PREFIX="🚀"\nif "$SCRIPT"; then\n  echo "Test 1 passed"\nelse\n  echo "Test 1 failed"\n  exit 1\nfi\n\n# Test 2: Title without prefix should fail\nEVENT2=$(create_event "Add new feature")\nexport GITHUB_EVENT_PATH="$EVENT2"\nexport INPUT_PREFIX="🚀"\nif "$SCRIPT"; then\n  echo "Test 2 failed (expected non‑zero exit)"\n  exit 1\nelse\n  echo "Test 2 passed"\nfi\n\n# Cleanup temporary files\nrm -f "$EVENT1" "$EVENT2"\n\necho "All tests passed"\n
